    source: "Al Jazeera",
    url: "https://www.aljazeera.com/news/2026/8/7/donald-trump-renews-effort-to-fire-federal-reserve-governor-lisa-cook?traffic_source=rss",
    time: "6 ore fa",
    pub_ts: 1786146016,
